# RW4DM_TEXT: GetUserText, Hyperlink, SetDocumentUserText, GetDocumentUserText: user text on objects and on the document. The script rw4dm_text_script.txt is generated by rw4dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW4_TEXT_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW4_TEXT_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw4dm_text_script.txt" 2>&1)" || { echo "$RW4_TEXT_OUT" | tail -40; echo "FAIL RW4DM_TEXT_run: script exited non-zero"; fail=1; RW4_TEXT_OUT=""; }
else
  RW4_TEXT_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw4dm_text_script.txt" 2>&1)" || { echo "$RW4_TEXT_OUT" | tail -40; echo "FAIL RW4DM_TEXT_run: script exited non-zero"; fail=1; RW4_TEXT_OUT=""; }
fi
rw4_text_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW4BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW4BEGIN_/ { exit } on { print }' <<<"$RW4_TEXT_OUT"; }
# rw4_text_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw4_text_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw4_text_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW4DM_TEXT_$name: $desc (objects: $got)"
  else echo "FAIL RW4DM_TEXT_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}

# rw4_text_lines STEP REGEX SED EXPECTED DESC SORTFLAG TAG: the lines of the step that match "history: REGEX", with "history: " removed and SED applied, joined by " | " (sorted
# bytewise first when the sixth argument is "sort"), read exactly EXPECTED ("-" = no line)
rw4_text_lines() {
  local blk got; blk="$(rw4_text_block "$1")"
  got="$({ grep -E "^history: $2" <<<"$blk" || true; } | sed -E 's/^history: //' | sed -E "$3" | { if [ "${6:-}" = sort ]; then LC_ALL=C sort; else cat; fi; } | paste -sd'|' - | sed 's/|/ | /g')"; [ -n "$got" ] || got="-"
  if [ "$got" = "$4" ]; then echo "ok   RW4DM_TEXT_$1_${7:-lines}: $5 (lines: $got)"
  else echo "FAIL RW4DM_TEXT_$1_${7:-lines}: $5 (got '$got', expected '$4')"; fail=1; { grep -E '^history: ' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw4_text_state t3 "-" "Hyperlink on object 3 stores the URL as that object's Hyperlink text" "Hyperlink 'http://example.org/a' set on 1 object\(s\)"
rw4_text_state d1 "-" "SetDocumentUserText Owner Alice and Site Zurich: GetDocumentUserText lists both, in key order" "Document user text Owner = Alice" "Document user text Site = Zurich"
rw4_text_state d3 "-" "SetDocumentUserText with a key and no value removes the key" "Document user text 'Site' removed"
rw4_text_lines t1 "[0-9]+: [A-Za-z]+ = " "s/x/x/" "1: Phase = One | 2: Phase = One" "SetUserText Phase One on 1 and 2: GetUserText of 1, 2 and 3 lists exactly those two" nosort lines
rw4_text_lines t2 "[0-9]+: [A-Za-z]+ = " "s/x/x/" "1: Phase = One | 2: Phase = One | 2: Zone = Z9" "a second key on object 2: the keys of an object come out in key order" nosort lines
rw4_text_lines t3 "[0-9]+: [A-Za-z]+ = " "s/x/x/" "3: Hyperlink = http://example.org/a" "Hyperlink on object 3 is stored as its Hyperlink text" nosort lines
rw4_text_lines t4 "[0-9]+: [A-Za-z]+ = " "s/x/x/" "3: Hyperlink = http://example.org/b" "a second Hyperlink replaces the first" nosort lines
rw4_text_lines d1 "(Owner|Site) = " "s/x/x/" "Owner = Alice | Site = Zurich" "GetDocumentUserText lists both document keys in key order" nosort lines
rw4_text_lines d2 "(Owner|Site) = " "s/x/x/" "Owner = Bob | Site = Zurich" "setting Owner again replaces its value, Site is kept" nosort lines
rw4_text_lines d3 "(Owner|Site) = " "s/x/x/" "Owner = Bob" "SetDocumentUserText with a key and no value removes the key" nosort lines
